    def preflight(repo, arcade, expected_commit):
        if socket.gethostname() != 'charlie-arcade' or platform.machine() != 'armv6l':
            raise ValueError('this upgrade is only for ARMv6 charlie-arcade; Pi 5 is forbidden')
        if os.geteuid() == 0 or arcade != Path.home() / 'arcade':
            raise ValueError('run as five using the existing home/arcade installation')
        if not re.fullmatch(r'[0-9a-f]{40}', expected_commit):
            raise ValueError('provide the full independently tested commit SHA')
        head = run(['git', '-C', str(repo), 'rev-parse', 'HEAD'])
        if head.returncode or head.stdout.strip() != expected_commit:
            raise ValueError('release checkout does not match pinned commit')
        dirty = run(['git', '-C', str(repo), 'status', '--porcelain', '--untracked-files=no'])
        if dirty.returncode or dirty.stdout:
            raise ValueError('release checkout has tracked modifications')
        service = run(['systemctl', 'is-active', 'charlie-arcade.service'])
        if service.returncode != 3 or service.stdout.strip() not in {'inactive', 'failed'}:
            raise ValueError('stop the existing arcade service first; installer never starts it')
        proc = run(['pgrep', '-x', 'retroarch'])
        if proc.returncode != 1:
            raise ValueError('RetroArch may still be running; stop it before installation')
        for name in FILES:
            p = arcade / name
            if p.is_symlink():
                raise ValueError('symlink at installed module path: ' + name)
            if not (repo / 'src' / name).is_file():
                raise ValueError('release file missing: ' + name)
        if digest(arcade / 'controller.py') != BASELINE_CONTROLLER:
>           raise ValueError('installed controller differs from inspected baseline')
